--[[
    Azeroth Intelligence — SI:7 word-set registry.
    Board IDs are indices inside the selected set. The host sends the set
    code once in START; later packets contain only compact card IDs.
]]

ArcadiaNexus = ArcadiaNexus or {}
ArcadiaNexus.SI7_WordSets = {}
local Sets = ArcadiaNexus.SI7_WordSets

local function ParsePairs(source)
    local words = {}
    for row in string.gmatch(source or "", "[^|]+") do
        local de, en = row:match("^(.-)~(.-)$")
        if de and en and de ~= "" and en ~= "" then
            words[#words + 1] = { deDE = de, enUS = en }
        end
    end
    return words
end

local function MakeCompounds(prefixes, suffixes)
    local words = {}
    for _, prefix in ipairs(prefixes) do
        for _, suffix in ipairs(suffixes) do
            words[#words + 1] = {
                deDE = prefix.de .. suffix.de,
                enUS = prefix.en .. " " .. suffix.en,
            }
        end
    end
    return words
end

