function Sets:Normalize(id) return self.data[id] and id or "AZEROTH" end
function Sets:Get(id) return self.data[self:Normalize(id)] end
function Sets:GetCount(id) local set = self:Get(id); return set.words and #set.words or 0 end
function Sets:IsNeutral(id) return self:Get(id).neutral == true end

function Sets:GetWord(id, index, locale)
    local set = self:Get(id)
    local word = set.words and set.words[index]
    if set.localized then
        local catalogue = ArcadiaNexus.HGM_Words
        return catalogue and catalogue:GetLocalizedWord(word, locale) or "?"
    end
    return word and (word[locale] or word.enUS or word.deDE) or "?"
end

function Sets:GetOptions()
    local L = ArcadiaNexus.GetLocaleTable("SI7") or {}
    local options = {}
    for _, id in ipairs(self.order) do
        options[#options + 1] = { key = id, label = L["wordset_" .. string.lower(id)] or id,
            tooltip = L["wordset_" .. string.lower(id) .. "_tooltip"] or "" }
    end
    return options
end

