Sets._bags = {}
function Sets:TakeBoard(id)
    id = self:Normalize(id)
    local count = self:GetCount(id)
    local bag = self._bags[id]
    if not bag or bag.pos + 24 > #bag.ids then
        local ids = {}
        for i = 1, count do ids[i] = i end
        ArcadiaNexus.ArrayUtils.Shuffle(ids)
        bag = { ids = ids, pos = 1 }
        self._bags[id] = bag
    end
    local board = {}
    for i = 1, 25 do board[i] = bag.ids[bag.pos + i - 1] end
    bag.pos = bag.pos + 25
    return board
end
